}

function plusLongueSousSuiteCroissante(tab) {
    let dp = []; // dp[i] sera le ième élément de la sous-suite (non pas la longueur, mais l'élément lui-même)
    for (let x of tab) {
        if (!dp.length || x > dp[dp.length-1]) {
            dp.push(x);
        } else {
            let low = 0;
            let high = dp.length - 1;
            while (low < high) {
                let mid = Math.floor((low + high) / 2);
                if (x <= dp[mid]) {
                    high = mid;
                } else {
                    low = mid + 1;
                }
            }
            dp[high] = x; // Remplacer l'élément actuel par x pour garder la séquence croissante
        }
    }

    return dp.length;
}
